                set.add(s.substring(i, i + L));
            }
            return set;
        };

    // Binary search for the maximum length
    int low = 0;
    int high = minLen;
    while (low < high) {
        int mid = (low + high + 1) / 2;
        // Check if there exists a substring of length mid that satisfies the condition
        java.util.Set<String> common = null;
