public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Basic validation
    if (n <= 0) {
        return "cannot be travelled";
    }
    if (start == null || end == null || start.length != n || end.length != n) {
        return "cannot be travelled";
    }
    if (paths == null) {
        // If start equals end, we can travel trivially
        for (int i = 0; i < n; i++) {
            if (start[i] != end[i]) {
                return "cannot be travelled";
            }
        }
        return "can be travelled";
    }

    // Helper to convert coordinate to string key
    java.util.function.Function<int[], String> coordToKey = coord -> {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < coord.length; i++) {
            if (i > 0) sb.append(',');
            sb.append(coord[i]);
        }
        return sb.toString();
    };

    // Build adjacency map
    java.util.Map<String, java.util.List<String>> adj = new java.util.HashMap<>();
    for (int[] path : paths) {
        if (path == null) continue;
        if (path.length == 2 * n) {
            int[] a = new int[n];
            int[] b = new int[n];
            System.arraycopy(path, 0, a, 0, n);
            System.arraycopy(path, n, b, 0, n);
            String keyA = coordToKey.apply(a);
            String keyB = coordToKey.apply(b);
            adj.computeIfAbsent(keyA, k -> new java.util.ArrayList<>()).add(keyB);
            adj.computeIfAbsent(keyB, k -> new java.util.ArrayList<>()).add(keyA);
        } else {
            // Unsupported path format; skip
            continue;
        }
    }

    String startKey = coordToKey.apply(start);
    String endKey = coordToKey.apply(end);

    // If start equals end, we can travel
    if (startKey.equals(endKey)) {
        return "can be travelled";
    }

    // If start or end not in graph, cannot travel
    if (!adj.containsKey(startKey) || !adj.containsKey(endKey)) {
        return "cannot be travelled";
    }

    // BFS
    java.util.Queue<String> queue = new java.util.ArrayDeque<>();
    java.util.Set<String> visited = new java.util.HashSet<>();
    queue.add(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String current = queue.poll();
        for (String neighbor : adj.getOrDefault(current, java.util.Collections.emptyList())) {
            if (neighbor.equals(endKey)) {
                return "can be travelled";
            }
            if (!visited.contains(neighbor)) {
                visited.add(neighbor);
                queue.add(neighbor);
            }
        }
    }

    return "cannot be travelled";
}

