    if (date == null) {
        return null;
    }
    String[] parts = date.trim().split("\\s+");
    if (parts.length != 3) {
        return null;
    }
    try {
        int month = Integer.parseInt(parts[0]);
        int day = Integer.parseInt(parts[1]);
        int year = Integer.parseInt(parts[2]);

        java.time.LocalDate localDate = java.time.LocalDate.of(year, month, day);

        java.time.format.TextStyle style = java.time.format.TextStyle.FULL;
        java.util.Locale locale = java.util.Locale.ENGLISH;

        String monthName = localDate.getMonth().getDisplayName(style, locale);
        String weekday = localDate.getDayOfWeek().getDisplayName(style, locale);

        return monthName + " " + day + ", " + year + " is a " + weekday;
    } catch (Exception e) {
        return null;
    }
}

