public String sortString(String s) {
    if (s == null) {
        return null;
    }
    int n = s.length();
    if (n == 0) {
        return "";
    }
    java.util.TreeMap<Character, Integer> freq = new java.util.TreeMap<>();
    for (char ch : s.toCharArray()) {
        freq.put(ch, freq.getOrDefault(ch, 0) + 1);
    }
    StringBuilder result = new StringBuilder(n);
    while (result.length() < n) {
        // Ascending phase
        Character next = freq.firstKey();
        if (next == null) {
            break;
        }
        result.append(next);
        decrementOrRemove(freq, next);
        char last = next;
        while (true) {
            Character higher = freq.higherKey(last);
            if (higher == null) {
                break;
            }
            result.append(higher);
            decrementOrRemove(freq, higher);
            last = higher;
        }
        if (result.length() == n) {
            break;
        }
        // Descending phase
        Character largest = freq.lastKey();
        if (largest == null) {
            break;
        }
        result.append(largest);
        decrementOrRemove(freq, largest);
        last = largest;
        while (true) {
            Character lower = freq.lowerKey(last);
            if (lower == null) {
                break;
            }
            result.append(lower);
            decrementOrRemove(freq, lower);
            last = lower;
        }
    }
    return result.toString();
}

private void decrementOrRemove(java.util.TreeMap<Character, Integer> map, Character key) {
    int count = map.get(key);
    if (count <= 1) {
        map.remove(key);
    } else {
        map.put(key, count - 1);
    }
}

