    // If there's only one step, the cost to reach the top is that step's cost
    if (n == 1) {
        return cost[0];
    }
    // Use two variables to keep track of the minimal cost to reach the previous two steps
    int prev = cost[0]; // cost to reach step 0
    int curr = cost[1]; // cost to reach step 1
    for (int i = 2; i < n; i++) {
        int next = Math.min(prev, curr) + cost[i];
        prev = curr;
        curr = next;
    }
    // The top can be reached from either of the last two steps
    return Math.min(prev, curr);
}

