public static int squarePermutations(int[] A) {
    if (A == null || A.length == 0) {
        return 1;
    }
    int n = A.length;
    int maxVal = 0;
    for (int v : A) {
        if (v > maxVal) maxVal = v;
    }
    int maxSum = maxVal * 2;
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int i = 1; i * i <= maxSum; i++) {
        isSquare[i * i] = true;
    }

    java.util.Arrays.sort(A);
    java.util.Map<Long, Integer> memo = new java.util.HashMap<>();
    int allMask = (1 << n) - 1;

    java.util.function.BiFunction<Integer, Integer, Integer> dfs = new java.util.function.BiFunction<>() {
        @Override
        public Integer apply(Integer mask, Integer lastIdx) {
            if (mask == allMask) {
                return 1;
            }
            long key = (((long) mask) << 4) | (lastIdx + 1);
            Integer cached = memo.get(key);
            if (cached != null) {
                return cached;
            }
            int count = 0;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) {
                    continue;
                }
                if (i > 0 && A[i] == A[i - 1] && (mask & (1 << (i - 1))) == 0) {
                    continue; // skip duplicate values at same recursion depth
                }
                if (lastIdx == -1 || isSquare[A[i] + A[lastIdx]]) {
                    count += apply(mask | (1 << i), i);
                }
            }
            memo.put(key, count);
            return count;
        }
    };

    return dfs.apply(0, -1);
}

